// Named places for `goto` and `places`: shrines, Koroks, towers, stables, villages and a few landmarks, with the game's world
// coordinates (the frame of `pos`). The data is runtime/control_places_data.inc (generated by tools/gen_places.py). The lookup
// has no game state in it, so tools/test_places.c tests it on its own.
#pragma once
#include <stdbool.h>
#include <stddef.h>

typedef enum { PLACE_SHRINE, PLACE_TOWER, PLACE_STABLE, PLACE_VILLAGE, PLACE_LANDMARK, PLACE_KOROK, PLACE_KINDS } PlaceKind;

typedef struct {
    PlaceKind kind;
    int number;        // shrine: the game's number (Dungeon005 = 5, from 0); tower: the game's tower number; others: 1.. in list order
    const char *key;   // the game's own id: Dungeon005, Tower07, RitoHatago, Korok H23
    const char *name;  // English name ("Ne'ez Yohma Shrine", "Rito Stable", Korok: the id)
    const char *sub;   // shrine: the quest title; Korok: the map square; else empty
    float x, y, z;
    bool ground;       // the position is a spot the game itself puts Link on (a start position), so he needs only a small lift
} Place;

const char *place_kind_name(PlaceKind kind);  // "shrine", "korok", ...
int place_kind_count(PlaceKind kind);
const Place *place_by_number(PlaceKind kind, int number);  // NULL when there is none

// What `goto` takes after the word goto: "shrine 5", "korok H23", "stable wetland", "oman au", "korok nearest", "nearest shrine".
// words are single words (split at spaces). `from` is where Link is now, for "nearest" (NULL when unknown).
// Returns the place, or NULL with the reason in why (no match, several matches with the first ones listed, bad number).
const Place *place_find(int nwords, char *const *words, const float from[3], char *why, size_t why_size);

// What `places` shows: kind filter (-1 = all kinds) and words that must each start a word of the name or title. Fills out[0..max)
// and returns how many places match in all.
int place_list(int kind, int nwords, char *const *words, const Place **out, int max);

// The kind a word names ("shrine", "shrines", "seed", "town", ...), or -1.
int place_kind_from_word(const char *word);
